syntax:
CREATE PROCEDURE procedure_name(param1 TYPE, param2 TYPE)
    LANGUAGE plpgsql AS $$
BEGIN
    UPDATE some_table SET column = value WHERE condition;
END;
$$;

CALL procedure_name(arg1, arg2);

example:
CREATE PROCEDURE give_department_raise(dept_id INTEGER, amount NUMERIC)
    LANGUAGE plpgsql AS $$
BEGIN
    UPDATE employees SET salary = salary + amount
        WHERE department_id = dept_id;
END;
$$;

CALL give_department_raise(1, 500);
